-- Bản SQLite của schema (chỉ dùng cho test). Giữ đồng bộ với database/migrations khi thêm cột.
CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password TEXT NOT NULL, phone TEXT, address TEXT, role TEXT NOT NULL DEFAULT 'customer', created_at TEXT, updated_at TEXT);
CREATE TABLE categories (id INTEGER PRIMARY KEY AUTOINCREMENT, parent_id INTEGER REFERENCES categories(id) ON DELETE SET NULL, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, description TEXT, sort_order INTEGER NOT NULL DEFAULT 0, created_at TEXT, updated_at TEXT);
CREATE TABLE products (id INTEGER PRIMARY KEY AUTOINCREMENT, category_id INTEGER REFERENCES categories(id) ON DELETE SET NULL, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, sku TEXT UNIQUE, short_description TEXT, description TEXT, price INTEGER NOT NULL DEFAULT 0, sale_price INTEGER, stock INTEGER NOT NULL DEFAULT 0 CHECK (stock >= 0), image TEXT, status TEXT NOT NULL DEFAULT 'active', is_featured INTEGER NOT NULL DEFAULT 0, has_variants INTEGER NOT NULL DEFAULT 0, created_at TEXT, updated_at TEXT, deleted_at TEXT);
CREATE TABLE product_options (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE, name TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, deleted_at TEXT, UNIQUE (product_id, name));
CREATE TABLE product_option_values (id INTEGER PRIMARY KEY AUTOINCREMENT, option_id INTEGER NOT NULL REFERENCES product_options(id) ON DELETE CASCADE, value TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, deleted_at TEXT, UNIQUE (option_id, value));
CREATE TABLE product_variants (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE, option_key TEXT NOT NULL, title TEXT NOT NULL, sku TEXT UNIQUE, price INTEGER NOT NULL DEFAULT 0, sale_price INTEGER, stock INTEGER NOT NULL DEFAULT 0 CHECK (stock >= 0), deleted_at TEXT, created_at TEXT, updated_at TEXT, UNIQUE (product_id, option_key));
CREATE TABLE product_variant_values (variant_id INTEGER NOT NULL REFERENCES product_variants(id) ON DELETE CASCADE, option_value_id INTEGER NOT NULL REFERENCES product_option_values(id) ON DELETE CASCADE, PRIMARY KEY (variant_id, option_value_id));
CREATE TABLE orders (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, user_id INTEGER REFERENCES users(id) ON DELETE SET NULL, customer_name TEXT NOT NULL, customer_email TEXT NOT NULL, customer_phone TEXT NOT NULL, shipping_address TEXT NOT NULL, note TEXT, subtotal INTEGER NOT NULL DEFAULT 0, shipping_fee INTEGER NOT NULL DEFAULT 0, discount INTEGER NOT NULL DEFAULT 0, voucher_code TEXT, total INTEGER NOT NULL DEFAULT 0, payment_method TEXT NOT NULL, payment_status TEXT NOT NULL DEFAULT 'unpaid', status TEXT NOT NULL DEFAULT 'pending', paid_at TEXT, created_at TEXT, updated_at TEXT);
CREATE TABLE order_items (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id INTEGER REFERENCES products(id) ON DELETE SET NULL, variant_id INTEGER REFERENCES product_variants(id) ON DELETE SET NULL, product_name TEXT NOT NULL, variant_label TEXT, sku TEXT, price INTEGER NOT NULL, quantity INTEGER NOT NULL, total INTEGER NOT NULL);
CREATE TABLE payments (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE, gateway TEXT NOT NULL, txn_ref TEXT NOT NULL, amount INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending', transaction_no TEXT, bank_code TEXT, response_code TEXT, gateway_create_date TEXT, raw_data TEXT, paid_at TEXT, created_at TEXT, updated_at TEXT, UNIQUE (gateway, txn_ref));
CREATE TABLE settings ("key" TEXT PRIMARY KEY, "value" TEXT, updated_at TEXT);
CREATE TABLE voucher_types (id INTEGER PRIMARY KEY AUTOINCREMENT, voucher_type TEXT NOT NULL);
INSERT INTO voucher_types (id, voucher_type) VALUES (1, 'Giảm theo danh mục'), (2, 'Giảm theo sản phẩm'), (3, 'Freeship');
CREATE TABLE discount_types (id INTEGER PRIMARY KEY AUTOINCREMENT, discount_type TEXT NOT NULL);
INSERT INTO discount_types (id, discount_type) VALUES (1, 'Giảm theo phần trăm'), (2, 'Giảm số tiền cố định');
CREATE TABLE vouchers (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, voucher_type INTEGER NOT NULL REFERENCES voucher_types(id), discount_type INTEGER NOT NULL REFERENCES discount_types(id), discount_value INTEGER, max_discount_amount INTEGER, min_spending INTEGER NOT NULL DEFAULT 0, max_usage_per_user INTEGER NOT NULL DEFAULT 1, start_date TEXT NOT NULL, end_date TEXT NOT NULL, is_active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE voucher_categories (voucher_id INTEGER NOT NULL REFERENCES vouchers(id) ON DELETE CASCADE, category_id INTEGER NOT NULL REFERENCES categories(id) ON DELETE CASCADE, PRIMARY KEY (voucher_id, category_id));
CREATE TABLE voucher_products (voucher_id INTEGER NOT NULL REFERENCES vouchers(id) ON DELETE CASCADE, product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE, PRIMARY KEY (voucher_id, product_id));
